/**
 * @file
 * @brief Public API for counter and timer drivers
 */

#ifndef ZEPHYR_INCLUDE_DRIVERS_COUNTER_H_
#define ZEPHYR_INCLUDE_DRIVERS_COUNTER_H_

/**
 * @brief Counter Interface
 * @defgroup counter_interface Counter Interface
 * @since 1.14
 * @version 1.0.0
 * @ingroup io_interfaces
 * @{
 */

#include <errno.h>
#include <stddef.h>
#include <zephyr/types.h>
#include <zephyr/device.h>
#include <zephyr/devicetree.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

/**@defgroup COUNTER_FLAGS Counter device capabilities
 * @{
 */

/**
 * @brief Counter count up flag.
 */
#define COUNTER_CONFIG_INFO_COUNT_UP BIT(0)

/**@} */

/**@defgroup COUNTER_TOP_FLAGS Flags used by @ref counter_top_cfg.
 * @{
 */

/**
 * @brief Counter prevent reset when top value is changed.
 *
 * If flag is set then counter is free running while top value is updated,
 * otherwise counter is reset(see @ref counter_set_top_value()).
 */
#define COUNTER_TOP_CFG_DONT_RESET BIT(0)

/**
 * @brief Instruct counter to reset itself if changing top value results in
 * counter going out of new top value bound.
 *
 * See @ref COUNTER_TOP_CFG_DONT_RESET.
 */
#define COUNTER_TOP_CFG_RESET_WHEN_LATE BIT(1)

/**@} */

/**@defgroup COUNTER_ALARM_FLAGS Alarm configuration flags
 *
 * @brief Used in @ref counter_alarm_cfg.
 * @{
 */

/**
 * @brief Counter alarm absolute value flag.
 *
 * Ticks relation to counter value. If set ticks are treated as absolute value
 * and if it is cleared ticks are relative to the counter reading performed
 * during the call.
 */
#define COUNTER_ALARM_CFG_ABSOLUTE BIT(0)

/**
 * @brief Counter alarmive expire immediately flag.
 *
 * Setting flag forces triggering alarm immediately if counter detects that
 * absolute alarm was set too late. Otherwise alarm will be triggered after full
 * period.
 *
 * Flag is valid only together with @ref COUNTER_ALARM_CFG_ABSOLUTE flag.
 */
#define COUNTER_ALARM_CFG_EXPIRE_WHEN_LATE BIT(1)

/**@} */

/**@defgroup COUNTER_GUARD_PERIOD_FLAGS Counter guard period flags
 *
 * @brief Used in @ref counter_set_guard_period and
 *		  @ref counter_get_guard_period.
 * @{
 */

/**
 * @briefIdentifies guard period needed for detection of late setting of
 *	 absolute alarm (see @ref counter_set_channel_alarm).
 */
#define COUNTER_GUARD_PERIOD_LATE_TO_SET BIT(0)

/**@} */

/**@defgroup COUNTER_CAPTURE_FLAGS Capture configuration flags
 *
 * @brief Used in @ref counter_capture_cfg.
 * @{
 */

/**
 * @brief Capture on rising edge.
 */
#define COUNTER_CAPTURE_CFG_EDGE_RISING BIT(0)

/**
 * @brief Capture on falling edge.
 */
#define COUNTER_CAPTURE_CFG_EDGE_FALLING BIT(1)

/**
 * @brief Capture on both edges.
 */
#define COUNTER_CAPTURE_CFG_EDGE_BOTH \
	(COUNTER_CAPTURE_CFG_EDGE_RISING | COUNTER_CAPTURE_CFG_EDGE_FALLING)

/**
 * @brief Counter capture mask for edge flags.
 */
#define COUNTER_CAPTURE_CFG_EDGE_MASK COUNTER_CAPTURE_CFG_EDGE_BOTH

/**
 * @brief Counter capture periodic flag.
 *
 * If set, capture event will be triggered repeatedly on every edge.
 * If cleared, capture event is one-shot.
 */
#define COUNTER_CAPTURE_CFG_PERIODIC BIT(2)

/**
 * @brief Reset counter on capture event.
 */
#define COUNTER_CAPTURE_CFG_RESET_COUNTER BIT(3)

/**@} */

/** @brief Alarm callback
 *
 * @param dev       Pointer to the device structure for the driver instance.
 * @param chan_id   Channel ID.
 * @param ticks     Counter value that triggered the alarm.
 * @param user_data User data.
 */
typedef void (*counter_alarm_callback_t)(const struct device *dev,
					 uint8_t chan_id, uint32_t ticks,
					 void *user_data);

/** @brief Alarm callback structure.
 */
struct counter_alarm_cfg {
	/** Callback called on alarm (cannot be NULL). */
	counter_alarm_callback_t callback;
	/** Number of ticks that triggers the alarm. It can be relative (to
	 *  now) or an absolute value (see @ref COUNTER_ALARM_CFG_ABSOLUTE).
	 */
	uint32_t ticks;
	/** User data returned in callback. */
	void *user_data;
	/** Alarm flags (see @ref COUNTER_ALARM_FLAGS). */
	uint32_t flags;
};

/** @brief Callback called when counter turns around.
 *
 * @param dev       Pointer to the device structure for the driver instance.
 * @param user_data User data provided in @ref counter_set_top_value.
 */
typedef void (*counter_top_callback_t)(const struct device *dev,
				       void *user_data);

/** @brief Structure with top value configuration.
 */
struct counter_top_cfg {
	/** Top value. */
	uint32_t ticks;
	/** Callback function (can be NULL). */
	counter_top_callback_t callback;
	/** User data passed to callback function (valid if callback is not
	 *  NULL).
	 */
	void *user_data;
	/** Flags (see @ref COUNTER_TOP_FLAGS). */
	uint32_t flags;
};

/** @brief Capture callback
 *
 * @param dev       Pointer to the device structure for the driver instance.
 * @param chan_id   Channel ID.
 * @param ticks     Captured counter value.
 * @param user_data User data.
 */
typedef void (*counter_capture_callback_t)(const struct device *dev,
					   uint8_t chan_id, uint32_t ticks,
					   void *user_data);

/** @brief Capture callback structure.
 */
struct counter_capture_cfg {
	/** Callback called on capture (cannot be NULL). */
	counter_capture_callback_t callback;
	/** User data returned in callback. */
	void *user_data;
	/** Capture flags (see @ref COUNTER_CAPTURE_FLAGS). */
	uint32_t flags;
};

/** @brief Structure with generic counter features.
 */
struct counter_config_info {
	/** Maximal (default) top value. */
	uint32_t max_top_value;
	/** Frequency of the source clock if synchronous events are counted. */
	uint32_t freq;
	/** Flags (see @ref COUNTER_FLAGS). */
	uint8_t flags;
	/** Number of channels that can be used for setting alarm.
	 *  @see counter_set_channel_alarm
	 */
	uint8_t channels;
};

/** @brief Container for counter channel information specified in devicetree.
 *
 * @see COUNTER_DT_SPEC_GET_BY_IDX
 * @see COUNTER_DT_SPEC_GET
 */
struct counter_dt_spec {
	/** Counter device instance. */
	const struct device *dev;
	/** Channel ID. */
	uint8_t chan_id;
	/** Capture flags. */
	uint32_t flags;
};

/**
 * @brief Static initializer for a @p counter_dt_spec
 *
 * This returns a static initializer for a @p counter_dt_spec structure given a
 * devicetree node identifier, a property specifying a Counter and an index.
 *
 * Example devicetree fragment:
 *
 *	/ {
 *		captures {
 *			test-counter-captures = <&counter0 1 COUNTER_CAPTURE_CFG_EDGE_RISING>,
 *						<&counter0 2 COUNTER_CAPTURE_CFG_EDGE_FALLING>;
 *			test-counter-capture-names = "cap1", "cap2";
 *		};
 *	};
 *
 * Example usage:
 *
 *	const struct counter_dt_spec spec =
 *		COUNTER_DT_SPEC_GET_BY_IDX(DT_PATH(captures),
 *					   test_counter_captures, 0);
 *	// Initializes 'spec' to:
 *	// {
 *	//         .dev = DEVICE_DT_GET(DT_NODELABEL(counter0)),
 *	//         .chan_id = 1,
 *	//         .flags = COUNTER_CAPTURE_CFG_EDGE_RISING,
 *	// }
 *
 * The 'counter' device must still be checked for readiness, e.g. using
 * device_is_ready().
 *
 * @param node_id devicetree node identifier
 * @param prop lowercase-and-underscores property name
 * @param idx logical index into "prop"
 *
 * @return static initializer for a struct counter_dt_spec for the property
 */
#define COUNTER_DT_SPEC_GET_BY_IDX(node_id, prop, idx)			       \
	{								       \
		.dev = DEVICE_DT_GET(DT_PHANDLE_BY_IDX(node_id, prop, idx)),   \
		.chan_id = DT_PHA_BY_IDX(node_id, prop, idx, channel),	       \
		.flags = DT_PHA_BY_IDX_OR(node_id, prop, idx, flags, 0),	\
	}

/**
 * @brief Static initializer for a @p counter_dt_spec from a "counters" property
 *
 * This is equivalent to
 * <tt>COUNTER_DT_SPEC_GET_BY_IDX(node_id, counters, idx)</tt>.
 *
 * @param node_id devicetree node identifier
 * @param idx logical index into "counters"
 *
 * @return static initializer for a struct counter_dt_spec for the property
 * @see COUNTER_DT_SPEC_GET_BY_IDX
 */
#define COUNTER_DT_SPEC_GET(node_id, idx) \
	COUNTER_DT_SPEC_GET_BY_IDX(node_id, counters, idx)

typedef int (*counter_api_start)(const struct device *dev);
typedef int (*counter_api_stop)(const struct device *dev);
typedef int (*counter_api_get_value)(const struct device *dev,
				     uint32_t *ticks);
typedef int (*counter_api_get_value_64)(const struct device *dev,
				     uint64_t *ticks);
typedef int (*counter_api_reset)(const struct device *dev);
typedef int (*counter_api_set_alarm)(const struct device *dev,
				     uint8_t chan_id,
				     const struct counter_alarm_cfg *alarm_cfg);
typedef int (*counter_api_cancel_alarm)(const struct device *dev,
					uint8_t chan_id);
typedef int (*counter_api_set_top_value)(const struct device *dev,
					 const struct counter_top_cfg *cfg);
typedef uint32_t (*counter_api_get_pending_int)(const struct device *dev);
typedef uint32_t (*counter_api_get_top_value)(const struct device *dev);
typedef uint32_t (*counter_api_get_guard_period)(const struct device *dev,
						 uint32_t flags);
typedef int (*counter_api_set_guard_period)(const struct device *dev,
					    uint32_t ticks,
					    uint32_t flags);
typedef uint32_t (*counter_api_get_freq)(const struct device *dev);
typedef int (*counter_api_set_capture)(const struct device *dev,
				       uint8_t chan_id,
				       const struct counter_capture_cfg *capture_cfg);
typedef int (*counter_api_cancel_capture)(const struct device *dev,
					  uint8_t chan_id);

__subsystem struct counter_driver_api {
	counter_api_start start;
	counter_api_stop stop;
	counter_api_get_value get_value;
	counter_api_get_value_64 get_value_64;
	counter_api_reset reset;
	counter_api_set_alarm set_alarm;
	counter_api_cancel_alarm cancel_alarm;
	counter_api_set_top_value set_top_value;
	counter_api_get_pending_int get_pending_int;
	counter_api_get_top_value get_top_value;
	counter_api_get_guard_period get_guard_period;
	counter_api_set_guard_period set_guard_period;
	counter_api_get_freq get_freq;
	counter_api_set_capture set_capture;
	counter_api_cancel_capture cancel_capture;
};

/**
 * @brief Check if counter is counting up.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 *
 * @retval true if counter is counting up.
 * @retval false if counter is counting down.
 */
__syscall bool counter_is_counting_up(const struct device *dev);

static inline bool z_impl_counter_is_counting_up(const struct device *dev)
{
	const struct counter_config_info *config =
		(const struct counter_config_info *)dev->config;

	return config->flags & COUNTER_CONFIG_INFO_COUNT_UP;
}

/**
 * @brief Get number of alarm channels.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 *
 * @return Number of alarm channels.
 */
__syscall uint8_t counter_get_num_of_channels(const struct device *dev);

static inline uint8_t z_impl_counter_get_num_of_channels(const struct device *dev)
{
	const struct counter_config_info *config =
		(const struct counter_config_info *)dev->config;

	return config->channels;
}

/**
 * @brief Get counter frequency.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 *
 * @return Frequency of the counter in Hz, or zero if the counter does
 * not have a fixed frequency.
 */
__syscall uint32_t counter_get_frequency(const struct device *dev);

static inline uint32_t z_impl_counter_get_frequency(const struct device *dev)
{
	const struct counter_config_info *config =
		(const struct counter_config_info *)dev->config;
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	return api->get_freq ? api->get_freq(dev) : config->freq;
}

/**
 * @brief Convert microseconds touyu counter ticks.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 * @param[in]  us           Microseconds.
 *
 * @return Converted ticks. Ticks will be saturated if exceed 32 bits.
 */
__syscall uint32_t counter_us_to_ticks(const struct device *dev, uint64_t us);

static inline uint32_t z_impl_counter_us_to_ticks(const struct device *dev,
						  uint64_t us)
{
	uint64_t ticks = (us * z_impl_counter_get_frequency(dev)) / USEC_PER_SEC;

	return (ticks > (uint64_t)UINT32_MAX) ? UINT32_MAX : ticks;
}

/**
 * @brief Convert counter ticks to microseconds.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 * @param[in]  ticks        Ticks.
 *
 * @return Converted microseconds.
 */
__syscall uint64_t counter_ticks_to_us(const struct device *dev, uint32_t ticks);

static inline uint64_t z_impl_counter_ticks_to_us(const struct device *dev,
						  uint32_t ticks)
{
	return ((uint64_t)ticks * USEC_PER_SEC) / z_impl_counter_get_frequency(dev);
}

/**
 * @brief Retrieve maximum top value that can be set.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 *
 * @return Maximum top value.
 */
__syscall uint32_t counter_get_max_top_value(const struct device *dev);

static inline uint32_t z_impl_counter_get_max_top_value(const struct device *dev)
{
	const struct counter_config_info *config =
		(const struct counter_config_info *)dev->config;

	return config->max_top_value;
}

/**
 * @brief Start counter device in free running mode.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 *
 * @retval 0 If successful.
 * @retval -errno Negative errno code on failure.
 */
__syscall int counter_start(const struct device *dev);

static inline int z_impl_counter_start(const struct device *dev)
{
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	return api->start(dev);
}

/**
 * @brief Stop counter device.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 *
 * @retval 0 If successful.
 * @retval -ENOTSUP if the device doesn't support stopping the
 *                        counter.
 */
__syscall int counter_stop(const struct device *dev);

static inline int z_impl_counter_stop(const struct device *dev)
{
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	return api->stop(dev);
}

/**
 * @brief Get current counter value.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 * @param[out] ticks        Pointer to where to store the current counter value
 *
 * @retval 0 If successful.
 * @retval -errno Negative error code on failure getting the counter value
 */
__syscall int counter_get_value(const struct device *dev, uint32_t *ticks);

static inline int z_impl_counter_get_value(const struct device *dev,
					   uint32_t *ticks)
{
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	return api->get_value(dev, ticks);
}

/**
 * @brief Get current counter 64-bit value.
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 * @param[out] ticks        Pointer to where to store the current counter value
 *
 * @retval 0 If successful.
 * @retval -errno Negative error code on failure getting the counter value
 */
__syscall int counter_get_value_64(const struct device *dev, uint64_t *ticks);

static inline int z_impl_counter_get_value_64(const struct device *dev,
					      uint64_t *ticks)
{
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	if (!api->get_value_64) {
		return -ENOSYS;
	}

	return api->get_value_64(dev, ticks);
}

/**
 * @brief Reset the counter to the initial value
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 *
 * @retval 0 If successful.
 * @retval -errno Negative error code on failure resetting the counter
 */
__syscall int counter_reset(const struct device *dev);

static inline int z_impl_counter_reset(const struct device *dev)
{
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	if (!api->reset) {
		return -ENOSYS;
	}

	return api->reset(dev);
}

/**
 * @brief Set a single shot alarm on a channel.
 *
 * After expiration alarm can be set again, disabling is not needed. When alarm
 * expiration handler is called, channel is considered available and can be
 * set again in that context.
 *
 * @note API is not thread safe.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 * @param[in]  chan_id      Channel ID.
 * @param[in]  alarm_cfg    Alarm configuration.
 *
 * @retval 0 If successful.
 * @retval -ENOTSUP if the request is not supported (device does not
 *                  support interrupt or requested channel).
 * @retval -EINVAL if alarm settings are invalid.
 * @retval -ETIME  if absolute alarm was set too late.
 * @retval -EBUSY  if alarm is already active.
 */
__syscall int counter_set_channel_alarm(const struct device *dev,
					uint8_t chan_id,
					const struct counter_alarm_cfg *alarm_cfg);

static inline int z_impl_counter_set_channel_alarm(const struct device *dev,
						   uint8_t chan_id,
						   const struct counter_alarm_cfg *alarm_cfg)
{
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	return api->set_alarm(dev, chan_id, alarm_cfg);
}

/**
 * @brief Cancel an alarm on a channel.
 *
 * @note API is not thread safe.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 * @param[in]  chan_id      Channel ID.
 *
 * @retval 0 If successful.
 * @retval -ENOTSUP if the counter was not started yet or the alarm was not
 *                  cancelled or the device does not support interrupting.
 */
__syscall int counter_cancel_channel_alarm(const struct device *dev,
					   uint8_t chan_id);

static inline int z_impl_counter_cancel_channel_alarm(const struct device *dev,
						      uint8_t chan_id)
{
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	return api->cancel_alarm(dev, chan_id);
}

/**
 * @brief Set counter top value.
 *
 * Function sets top value and optionally resets the counter to 0 or max value
 * depending on counter direction. On turnaround, counter can be reset and
 * optional callback is periodically called. Top value can only be changed when
 * there is no active channel alarm.
 *
 * @ref COUNTER_TOP_CFG_DONT_RESET prevents counter reset. When counter is
 * running while top value is updated, it is possible that counter progresses
 * outside the new top value. In that case, error is returned and optionally
 * driver can reset the counter (see @ref COUNTER_TOP_CFG_RESET_WHEN_LATE).
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 * @param[in]  cfg          Configuration. Cannot be NULL.
 *
 * @retval 0 If successful.
 * @retval -ENOTSUP if the request is not supported (e.g. top value cannot be
 *		    changed or counter cannot/must be reset during top value
 *		    update).
 * @retval -EBUSY if any alarm is active.
 * @retval -ETIME if @ref COUNTER_TOP_CFG_DONT_RESET was set and new top value
 *		  is smaller than current counter value (counter counting up).
 */
__syscall int counter_set_top_value(const struct device *dev,
				    const struct counter_top_cfg *cfg);

static inline int z_impl_counter_set_top_value(const struct device *dev,
					       const struct counter_top_cfg
					       *cfg)
{
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	return api->set_top_value(dev, cfg);
}

/**
 * @brief Function to get pending interrupts
 *
 * The purpose of this function is to return the interrupt
 * status register for the device.
 * This is especially useful when waking up from
 * low power states to check the wake up source.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 *
 * @retval 1 if any counter interrupt is pending.
 * @retval 0 if no counter interrupt is pending.
 */
__syscall int counter_get_pending_int(const struct device *dev);

static inline int z_impl_counter_get_pending_int(const struct device *dev)
{
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	return api->get_pending_int(dev);
}

/**
 * @brief Retrieve current top value.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 *
 * @return Top value.
 */
__syscall uint32_t counter_get_top_value(const struct device *dev);

static inline uint32_t z_impl_counter_get_top_value(const struct device *dev)
{
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	return api->get_top_value(dev);
}

/**
 * @brief Set guard period in counter ticks.
 *
 * Function sets how many ticks before the counter wraps around it is considered
 * too late to set an absolute alarm. If the driver detects that an absolute
 * alarm is set too late, it can either return an error or expire the alarm
 * immediately (see @ref COUNTER_ALARM_CFG_EXPIRE_WHEN_LATE).
 *
 * Guard period should be set according to maximum time of interrupt latency.
 * Setting it to 0 disables detection. If the counter frequency is high and the
 * counter top value is small, it is not recommended to disable guard period
 * because if an absolute alarm is set right before the counter wraps around, it
 * may take a full period before the alarm expires.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 * @param[in]  ticks        Guard period in counter ticks.
 * @param[in]  flags        See @ref COUNTER_GUARD_PERIOD_FLAGS.
 *
 * @retval 0 if successful
 * @retval -ENOTSUP if function or flags are not supported
 * @retval -EINVAL if ticks value is invalid
 */
__syscall int counter_set_guard_period(const struct device *dev,
				       uint32_t ticks,
				       uint32_t flags);

static inline int z_impl_counter_set_guard_period(const struct device *dev,
						  uint32_t ticks, uint32_t flags)
{
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	if (!api->set_guard_period) {
		return -ENOTSUP;
	}

	return api->set_guard_period(dev, ticks, flags);
}

/**
 * @brief Return guard period.
 *
 * See @ref counter_set_guard_period.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 * @param[in]  flags        See @ref COUNTER_GUARD_PERIOD_FLAGS.
 *
 * @return Guard period given in counter ticks or 0 if function or flags are
 *	   not supported.
 */
__syscall uint32_t counter_get_guard_period(const struct device *dev,
					    uint32_t flags);

static inline uint32_t z_impl_counter_get_guard_period(const struct device *dev,
						       uint32_t flags)
{
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	return (api->get_guard_period) ? api->get_guard_period(dev, flags) : 0;
}

/**
 * @brief Set a capture on a channel.
 *
 * @note API is not thread safe.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 * @param[in]  chan_id      Channel ID.
 * @param[in]  capture_cfg  Capture configuration.
 *
 * @retval 0 If successful.
 * @retval -ENOTSUP if the request is not supported (device does not
 *                  support interrupt or requested channel).
 * @retval -EINVAL if capture settings are invalid.
 * @retval -EBUSY  if capture is already active.
 */
__syscall int counter_set_channel_capture(const struct device *dev,
					  uint8_t chan_id,
					  const struct counter_capture_cfg *capture_cfg);

static inline int z_impl_counter_set_channel_capture(const struct device *dev,
						     uint8_t chan_id,
						     const struct counter_capture_cfg *capture_cfg)
{
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	if (!api->set_capture) {
		return -ENOSYS;
	}

	return api->set_capture(dev, chan_id, capture_cfg);
}

/**
 * @brief Set a capture on a channel from a @p counter_dt_spec.
 *
 * @param[in]  spec         Counter specification from devicetree.
 * @param[in]  capture_cfg  Capture configuration.
 *
 * @return A value from counter_set_channel_capture().
 */
static inline int counter_set_channel_capture_dt(const struct counter_dt_spec *spec,
						 struct counter_capture_cfg *capture_cfg)
{
	capture_cfg->flags |= spec->flags;
	return counter_set_channel_capture(spec->dev, spec->chan_id, capture_cfg);
}

/**
 * @brief Cancel a capture on a channel.
 *
 * @note API is not thread safe.
 *
 * @param[in]  dev          Pointer to the device structure for the driver
 *			    instance.
 * @param[in]  chan_id      Channel ID.
 *
 * @retval 0 If successful.
 * @retval -ENOTSUP if the counter was not started yet or the capture was not
 *                  cancelled or the device does not support interrupting.
 */
__syscall int counter_cancel_channel_capture(const struct device *dev,
					     uint8_t chan_id);

static inline int z_impl_counter_cancel_channel_capture(const struct device *dev,
							uint8_t chan_id)
{
	const struct counter_driver_api *api =
		(struct counter_driver_api *)dev->api;

	if (!api->cancel_capture) {
		return -ENOSYS;
	}

	return api->cancel_capture(dev, chan_id);
}

/**
 * @brief Cancel a capture on a channel from a @p counter_dt_spec.
 *
 * @param[in]  spec         Counter specification from devicetree.
 *
 * @return A value from counter_cancel_channel_capture().
 */
static inline int counter_cancel_channel_capture_dt(const struct counter_dt_spec *spec)
{
	return counter_cancel_channel_capture(spec->dev, spec->chan_id);
}

/**
 * @brief Validate that Counter device is ready.
 *
 * @param spec Counter specification from devicetree
 *
 * @retval true if the Counter device is ready for use
 * @retval false if the Counter device is not ready for use
 */
static inline bool counter_is_ready_dt(const struct counter_dt_spec *spec)
{
	return device_is_ready(spec->dev);
}

